merge into RRL_SCHEMA_MIGRATIONS t using(select '2026-10-12-388-return-current-profile-matrix' MIGRATION_ID from dual)s on(t.MIGRATION_ID=s.MIGRATION_ID)when not matched then insert(MIGRATION_ID,DESCRIPTION,APPLIED_AT,APPLIED_BY,SCRIPT_NAME,ROLLBACK_SCRIPT,STATUS)values(s.MIGRATION_ID,'Existing return owner bridges approved unit/lot/profile matrix to shared disposition resolver; flexible UNIT accepted, current saved profile versions checked',sysdate,user,'apply.sql','rollback.sql','APPLIED');
